\copy (with pick as ( select id from site.bp_shared_logs where position('CEntityComponentCommodityUIProvider::' in scrubbed) > 0 and position('planet cells:' in scrubbed) > 0 and position('[QuantumTravel]' in scrubbed) > 0 and length(scrubbed) between 400000 and 1200000 order by id limit 8 ) select l.id || ' ' || replace(encode(convert_to(l.scrubbed,'UTF8'),'base64'), E'\n','') from site.bp_shared_logs l join pick p on p.id = l.id order by l.id) to stdout
